  `amountPaid` float DEFAULT NULL,
  `transactionId` varchar(100) DEFAULT NULL,
  `totalAmount` float DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
