--
-- Table structure for table `transactions`
--

DROP TABLE IF EXISTS `transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `transactions` (
  `id` varchar(100) NOT NULL,
  `userId` varchar(100) DEFAULT NULL,
  `createdAt` datetime DEFAULT NULL,
  `stripeId` varchar(100) DEFAULT NULL,
  `status` varchar(100) DEFAULT NULL,
  `response` varchar(100) DEFAULT NULL,
  `bookingId` varchar(100) DEFAULT NULL,
  `payableAmount` float DEFAULT NULL,
  `updatedAt` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `transactions_bookings_FK` (`bookingId`),
  CONSTRAINT `transactions_bookings_FK` FOREIGN KEY (`bookingId`) REFERENCES `bookings` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

